import * as T from './vendor/three.module.js';
import {skyAt} from './world-time.js';
export function createWinterSky(scene,hemi,sun,fill,world){
 const canvas=document.createElement('canvas');canvas.width=canvas.height=64;const ctx=canvas.getContext('2d');ctx.strokeStyle='#ffffff';ctx.lineWidth=2.6;ctx.lineCap='round';ctx.translate(32,32);for(let i=0;i<6;i++){ctx.save();ctx.rotate(i*Math.PI/3);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,-26);for(const y of [-12,-20]){ctx.moveTo(0,y);ctx.lineTo(-5,y+4);ctx.moveTo(0,y);ctx.lineTo(5,y+4);}ctx.stroke();ctx.restore();}
 const texture=new T.CanvasTexture(canvas),count=280,positions=new Float32Array(count*3);let seed=771;const rand=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646;};const seeds=[];for(let i=0;i<count;i++)seeds.push({x:(rand()-.5)*80,z:(rand()-.5)*80,y:rand()*27,s:.4+rand()*.65,phase:rand()*6});
 const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(positions,3));const snow=new T.Points(geometry,new T.PointsMaterial({map:texture,color:'#f0f7ff',size:.19,transparent:true,opacity:.58,depthWrite:false,alphaTest:.015}));snow.frustumCulled=false;scene.add(snow);
 const a=new T.Color(),b=new T.Color();let skyState=skyAt(12),hour=12,snowEnabled=true;
 try{snowEnabled=localStorage.getItem('winter-snow')!=='off';}catch{}document.querySelector('#snow-enabled').checked=snowEnabled;
 const updateTime=detail=>{hour=detail.hour;skyState=skyAt(hour);};if(window.labWorldTime)updateTime(window.labWorldTime);window.addEventListener('lab:time',e=>updateTime(e.detail));document.querySelector('#snow-enabled')?.addEventListener('change',e=>{snowEnabled=e.target.checked;try{localStorage.setItem('winter-snow',snowEnabled?'on':'off');}catch{}});
 return{update(time,still,target,brightness=1){const {a:lo,b:hi,t}=skyState;const color=(x,y)=>a.set(x).lerp(b.set(y),t);scene.background.copy(color(lo.sky,hi.sky));scene.fog.color.copy(color(lo.horizon,hi.horizon));hemi.intensity=T.MathUtils.lerp(lo.ambient,hi.ambient,t);hemi.color.set('#b3c6df');hemi.groundColor.set('#586a76');sun.color.copy(color(lo.sun,hi.sun));sun.intensity=T.MathUtils.lerp(lo.light,hi.light,t)*brightness;fill.intensity=.22;fill.color.set('#ebc7a1');world.setSky?.(color(lo.sky,hi.sky).clone(),color(lo.horizon,hi.horizon).clone(),hour);snow.visible=snowEnabled;const clock=still?0:time;for(let i=0;i<count;i++){const f=seeds[i];positions[i*3]=target.x+f.x+Math.sin(clock*.15+f.phase)*1.8;positions[i*3+1]=((f.y-clock*f.s)%27+27)%27;positions[i*3+2]=target.z+f.z+Math.cos(clock*.12+f.phase);}geometry.attributes.position.needsUpdate=true;}};
}
